                                },
                                "offset": {
                                    "type": "number",
                                    "default": 0.0,
                                    "description": "offset of this needle. E.g. if at 5.0 (2nd digit needle at zero) but this needle show ~4.6 enter offset 0.4."
                                }
                            }
