                    }
                }
            ]
        },
        "meterOCRBBBox": {
            "title": "bounding-box with a rectangle",
            "allOf": [
                {
                    "$ref": "#/definitions/meterOCRBB"
                },
                {
                    "properties": {
                        "type": {
                            "type": "string",
                            "enum": [
                                "box"
                            ]
                        },
