                }
            ]
        },
        "channels": {
            "type": "array",
            "items": {
                "oneOf": [
                    {
                        "$ref": "#/definitions/channel"
                    }
                ]
            }
        },
        "meters": {
            "type": "array",
            "minItems": 1,
            "items": {
                "oneOf": [
                    {
                        "$ref": "#/definitions/meterInvalid"
                    },
                    {
                        "$ref": "#/definitions/meterS0"
                    },
                    {
                        "$ref": "#/definitions/meterD0"
                    },
                    {
                        "$ref": "#/definitions/meterSML"
                    },
                    {
                        "$ref": "#/definitions/meterRandom"
                    },
                    {
                        "$ref": "#/definitions/meterFile"
                    },
                    {
                        "$ref": "#/definitions/meterExec"
                    },
                    {
                        "$ref": "#/definitions/meterFluksoV2"
                    },
                    {
                        "$ref": "#/definitions/meterOCR"
                    },
                    {
                        "$ref": "#/definitions/meterOMS"
                    },
                    {
                        "$ref": "#/definitions/meterW1therm"
                    }
                ]
            }
        },
        "push": {
            "type": "array",
            "minItems": 0,
            "items": {
                "oneOf": [
                    {
                        "$ref": "#/definitions/pushdataentry"
                    }
                ]
            },
            "description": "list of middlewares receiving push data (i.e. non aggregated live data in single http request)"
        }
    },
    "type": "object",
    "properties": {
        "retry": {
            "type": "integer",
            "description": "How long to sleep between failed requests, in seconds"
        },
        "daemon": {
            "type": "boolean",
            "default": "true",
            "description": "Enable daemon mode"
        },
        "verbosity": {
            "type": "integer",
            "enum": [
                0,
                5,
                10,
                15
            ],
            "description": "0 = log_error or log-warning, 5 = log_info, 10 = log-debug, 15 = log_finest",
            "default": 0
        },
        "log": {
            "type": "string",
            "description": "path to log file"
        },
        "push": {
            "$ref": "#/definitions/push"
        },
        "local": {
            "$ref": "#/definitions/local"
        },
        "meters": {
            "$ref": "#/definitions/meters"
        }
    },
    "required": [
        "daemon",
        "log"
    ]
}

{
    "title": "A JSON Schema for apis.json, version 0.14",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "additionalProperties": false,
    "patternProperties": {
        "^X-": {
            "type": "object"
        }
    },
    "definitions": {
        "maintainers": {
            "description": "The person or organization responsible for maintaining the API",
            "required": [
                "name"
            ],
            "properties": {
                "name": {
                    "type": "string",
                    "description": "name",
                    "minLength": 5
                }
            },
            "additionalProperties": {
                "type": "string"
            }
        },
        "apis": {
            "description": "The description of the API",
            "oneOf": [
                {
                    "required": [
                        "name",
                        "description",
                        "image",
                        "baseURL",
                        "humanURL",
                        "properties",
                        "contact"
                    ],
                    "properties": {
                        "name": {
                            "type": "string",
                            "description": "name",
                            "minLength": 5
                        },
                        "description": {
                            "type": "string",
                            "description": "description of the API",
                            "minLength": 5
                        },
                        "image": {
                            "type": "string",
                            "description": "URL of an image representing the API"
                        },
                        "baseURL": {
                            "type": "string",
                            "pattern": "^(http)|(https)://(.*)$",
                            "description": "baseURL"
                        },
                        "humanURL": {
                            "type": "string",
                            "pattern": "^(http)|(https)://(.*)$",
                            "description": "humanURL"
                        },
                        "tags": {
                            "type": "array",
                            "items": {
                                "type": "string",
                                "minLength": 1
                            },
                            "description": "tags to describe the API"
                        },
                        "properties": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/urls"
                            },
                            "description": "URLs"
                        },
                        "contact": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/contact"
                            },
                            "description": "Contact to reach if questions about API"
                        },
                        "meta": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/metaInformation"
                            }
                        }
                    }
                }
            ]
        },
        "metaInformation": {
            "description": "Metadata about the API",
            "required": [
                "key",
                "value"
            ],
            "properties": {
                "key": {
                    "type": "string"
                },
                "value": {
                    "type": "string"
                }
            }
        },
        "contact": {
            "description": "Information on contacting the API support",
            "required": [
                "FN"
            ],
            "additionalProperties": true,
            "patternProperties": {
                "^X-": {
                    "type": "string"
                }
            },
            "properties": {
                "FN": {
                    "type": "string",
                    "minLength": 1
                },
                "email": {
                    "type": "string",
                    "format": "email"
                },
                "organizationName": {
                    "type": "string",
                    "minLength": 1
                },
                "adr": {
                    "type": "string"
                },
                "tel": {
                    "type": "string",
                    "minLength": 1
                },
                "X-twitter": {
                    "type": "string"
                },
                "X-github": {
                    "type": "string"
                },
                "photo": {
                    "type": "string",
                    "pattern": "^(http)|(https)://(.*)$"
                },
                "vCard": {
                    "type": "string",
                    "pattern": "^(http)|(https)://(.*)$"
                },
                "url": {
                    "type": "string",
                    "pattern": "^(http)|(https)://(.*)$"
                }
            }
        },
        "urls": {
            "description": "A representation of a URL",
            "required": [
                "type",
                "url"
            ],
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^(Swagger)$|^(RAML)$|^(Blueprint)$|^(WADL)$|^(WSDL)$|^(TermsOfService)$|^(InterfaceLicense)$|^(StatusPage)$|^(Pricing)$|^(Forums)$|^(AlertsTwitterHandle)$|^(X-[A-Za-z0-9\\-]*)$"
                },
                "url": {
                    "type": "string",
                    "pattern": "^(http)|(https)://(.*)$"
                }
            }
        },
        "tags": {
            "description": "A consistent set of tag to apply to a description"
        },
        "include": {
            "description": "Include other APIs.json file",
            "required": [
                "name",
                "url"
            ],
            "properties": {
                "name": {
                    "type": "string",
                    "minLength": 1
                },
                "url": {
                    "type": "string",
                    "pattern": "^(http)|(https)://(.*)$"
                }
            }
        }
    },
    "required": [
        "name",
        "description",
        "url",
        "apis",
        "maintainers",
        "tags"
    ],
    "properties": {
        "name": {
            "type": "string",
            "description": "The name of the service described",
            "minLength": 5
        },
        "description": {
            "type": "string",
            "description": "Description of the service",
            "minLength": 5
        },
        "url": {
            "type": "string",
            "description": "URL where the apis.json file will live",
            "pattern": "^(http)|(https)://(.*)$"
        },
        "image": {
            "type": "string",
            "description": "Image to represent the API"
        },
        "created": {
            "type": "string",
            "format": "date",
            "description": "Date when the file was created"
        },
        "modified": {
            "type": "string",
            "format": "date",
            "description": "Date when the file was modified"
        },
        "specificationVersion": {
            "type": "string",
            "description": "APIs.json spec version, latest is 0.14"
        },
        "apis": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/apis"
            },
            "description": "All the APIs of this service"
        },
        "maintainers": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/contact"
            },
            "description": "Maintainers of the apis.json file"
        },
        "tags": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/tags"
            },
            "description": "Tags to describe the service"
        },
        "include": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/include"
            },
            "description": "Links to other apis.json definitions included in this service"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema",
    "additionalProperties": false,
    "definitions": {
        "dataset": {
            "description": "Files in the archive that contain the data of interest",
            "items": {
                "description": "Use 'data:<mime-type>[;base64],<...>' for data URIs, 'file:<...>' for file references, and 'http://<host>/<file>' for external references.",
                "title": "Data-URI encoded reference.",
                "type": "string"
            },
            "minitems": "1",
            "title": "A set of files",
            "type": "array"
        },
        "date": {
            "_format": "date-time",
            "description": "ISO 8601 date.",
            "title": "Datestamp",
            "type": "string"
        },
        "description": {
            "description": "The detailed description of the data element",
            "title": "Description",
            "type": "string"
        },
        "geometry": {
            "description": "The geometry of the data element",
            "properties": {
                "data": {
                    "$ref": "#/definitions/dataset"
                },
                "type": {
